// Hand-written. Not generated by Speakeasy.
//
// The sibling file handles lists of strings. This one handles a list of
// objects, which supported_scopes is, and which needed a different rule.
//
// Authlete sorts supported_scopes by name. Measured against the live API:
//
//	sent : zeta, alpha, mike, beta
//	back : alpha, beta, mike, zeta
//
// Terraform compares lists by position, so any service with two scopes not
// already in alphabetical order shows a diff on every plan, and because the
// resource reads as changing, the computed attributes on it plan as unknown
// too. That is roughly 180 lines of plan output for a service nobody edited.
//
// Holding the stored order whenever the elements match, as the string lists
// do, is wrong here: an element is an object, and replacing the configuration
// with what is stored would silently discard an edit to a scope's description.
//
// So the match is made by name, and an edit is still a difference. A scope
// present in the configuration must be satisfied by the stored one: every
// field the configuration states must already hold. A field it leaves out is
// not an opinion, because these are all optional and computed, and Authlete
// fills in default_entry whether or not it was asked to.
package planmodifiers

import (
	"context"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

// KeepOrderByKeyWhenSatisfied returns a plan modifier for a list of objects
// that Authlete reorders, matching elements on the named attribute.
func KeepOrderByKeyWhenSatisfied(key string) planmodifier.List {
	return keepOrderByKey{key: key}
}

type keepOrderByKey struct{ key string }

func (m keepOrderByKey) Description(_ context.Context) string {
	return "keeps the order already in state when the configuration describes the " +
		"same entries, matched on " + m.key + ", because Authlete sorts this list " +
		"and Terraform compares lists by position"
}

func (m keepOrderByKey) MarkdownDescription(ctx context.Context) string {
	return m.Description(ctx)
}

func (m keepOrderByKey) PlanModifyList(ctx context.Context, req planmodifier.ListRequest, resp *planmodifier.ListResponse) {
	// Creation has no prior order to keep.
	if req.State.Raw.IsNull() {
		return
	}
	if req.StateValue.IsNull() || req.StateValue.IsUnknown() {
		return
	}
	if req.ConfigValue.IsNull() || req.ConfigValue.IsUnknown() {
		return
	}

	stored, ok := objectsByKey(ctx, req.StateValue.Elements(), m.key)
	if !ok {
		return
	}
	configured, ok := objectsByKey(ctx, req.ConfigValue.Elements(), m.key)
	if !ok {
		return
	}

	// A scope added or removed is a real change, and so is a duplicate name,
	// which objectsByKey reports by returning a shorter map than the slice.
	if len(stored) != len(configured) ||
		len(stored) != len(req.StateValue.Elements()) ||
		len(configured) != len(req.ConfigValue.Elements()) {
		return
	}

	for name, cfg := range configured {
		got, present := stored[name]
		if !present || !satisfiedBy(cfg, got) {
			return
		}
	}

	resp.PlanValue = req.StateValue
}

// objectsByKey indexes object elements by the value of one attribute. The
// second result is false when an element is not an object, the key is absent,
// or the key is null or unknown, in which case no reordering is attempted.
func objectsByKey(ctx context.Context, vals []attr.Value, key string) (map[string]map[string]tftypes.Value, bool) {
	out := make(map[string]map[string]tftypes.Value, len(vals))

	for _, val := range vals {
		tfVal, err := val.ToTerraformValue(ctx)
		if err != nil {
			return nil, false
		}

		fields := map[string]tftypes.Value{}
		if err := tfVal.As(&fields); err != nil {
			return nil, false
		}

		raw, present := fields[key]
		if !present || raw.IsNull() || !raw.IsKnown() {
			return nil, false
		}

		var name string
		if err := raw.As(&name); err != nil {
			return nil, false
		}
		out[name] = fields
	}

	return out, true
}

// satisfiedBy reports whether every field the configuration states already
// holds in the stored object. A null field in the configuration states
// nothing: every attribute here is optional and computed, so leaving one out
// means accepting whatever Authlete chose.
func satisfiedBy(cfg, stored map[string]tftypes.Value) bool {
	for name, want := range cfg {
		if want.IsNull() {
			continue
		}
		if !want.IsKnown() {
			return false
		}
		got, present := stored[name]
		if !present || !want.Equal(got) {
			return false
		}
	}
	return true
}
